import java.util.*;

public class Main {
    static final int MOD = 1000000007;
    static Map<Integer, Integer> mp = new HashMap<>();

    // Modular arithmetic utilities
    static int add(int a, int b) {
        long res = (long)a + b;
        if (res >= MOD) res -= MOD;
        return (int)res;
    }

    static int sub(int a, int b) {
        long res = (long)a - b;
        if (res < 0) res += MOD;
        return (int)res;
    }

    static int mul(int a, int b) {
        return (int)((long)a * b % MOD);
    }

    static int pow(int a, int n) {
        int res = 1;
        while (n > 0) {
            if ((n & 1) == 1) res = mul(res, a);
            a = mul(a, a);
            n >>= 1;
        }
        return res;
    }

    static int inv(int a) {
        return pow(a, MOD - 2);
    }

    static int div(int a, int b) {
        return mul(a, inv(b));
    }

    // Generate all permutations of {0,0,0,1,1,1} in lexicographic order
    static void initMap() {
        int[] v = {0, 0, 0, 1, 1, 1};
        int id = 0;
        do {
            int tt = 0;
            for (int k = 0; k < 6; ++k) {
                if (v[k] == 1) tt |= (1 << k);
            }
            mp.put(tt, id);
            id++;
        } while (nextPermutation(v));
    }

    static boolean nextPermutation(int[] a) {
        int i = a.length - 2;
        while (i >= 0 && a[i] >= a[i + 1]) i--;
        if (i < 0) return false;
        int j = a.length - 1;
        while (a[j] <= a[i]) j--;
        swap(a, i, j);
        reverse(a, i + 1, a.length - 1);
        return true;
    }

    static void swap(int[] a, int i, int j) {
        int tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
    }

    static void reverse(int[] a, int l, int r) {
        while (l < r) {
            swap(a, l, r);
            l++;
            r--;
        }
    }

    static void init(int[][] pers, Scanner sc) {
        int N = sc.nextInt();
        int s = 3 - (N + 1) / 2;
        // Set identity for rows outside the middle block
        for (int i = 0; i < s; ++i) pers[i][i] = 1;
        for (int i = s + N; i < 6; ++i) pers[i][i] = 1;
        // Read the N x N probability matrix
        for (int i = s; i < s + N; ++i) {
            for (int j = s; j < s + N; ++j) {
                int p = sc.nextInt();
                pers[i][j] = div(p, 100);
            }
        }
    }

    static int[] solve(int[][] pers, int al) {
        int[] l_nums = new int[1 << 20];
        for (int xx = 0; xx < (1 << 18); ++xx) {
            boolean[][] haves = new boolean[3][6];
            int per = 1;
            for (int i = 0; i < 3; ++i) {
                for (int j = 0; j < 6; ++j) {
                    int k = i * 6 + j;
                    if ((xx & (1 << k)) != 0) {
                        haves[i][j] = true;
                        per = mul(per, pers[al + i][j]);
                    } else {
                        per = mul(per, sub(1, pers[al + i][j]));
                    }
                }
            }
            int flags = 0;
            for (int i = 0; i < 6; ++i) {
                if (!haves[0][i]) continue;
                for (int j = 0; j < 6; ++j) {
                    if (!haves[1][j]) continue;
                    if (i == j) continue;
                    for (int k = 0; k < 6; ++k) {
                        if (!haves[2][k]) continue;
                        if (i == k || j == k) continue;
                        int anum = (1 << i) | (1 << j) | (1 << k);
                        int id = mp.get(anum);
                        flags |= (1 << id);
                    }
                }
            }
            l_nums[flags] = add(l_nums[flags], per);
        }
        return l_nums;
    }

    static int reverseBits(int x, int bits) {
        int res = 0;
        for (int i = 0; i < bits; ++i) {
            if ((x & (1 << i)) != 0) {
                res |= (1 << (bits - 1 - i));
            }
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        initMap();

        int[][] pers = new int[6][6];
        init(pers, sc);

        int[] u_nums = solve(pers, 0);
        int[] d_nums = solve(pers, 3);

        // SOS DP: for each mask, sum over all subsets
        for (int x = 1; x < (1 << 20); x <<= 1) {
            for (int i = 0; i < (1 << 20); ++i) {
                if ((i & x) == 0) {
                    d_nums[i | x] = add(d_nums[i | x], d_nums[i]);
                }
            }
        }

        int answer = 0;
        int fullMask = (1 << 20) - 1;
        for (int i = 0; i < (1 << 20); ++i) {
            if (u_nums[i] != 0) {
                int need = reverseBits(i, 20);
                int complementNeed = fullMask ^ need;
                int probBottom = d_nums[complementNeed];
                int term = mul(u_nums[i], sub(1, probBottom));
                answer = add(answer, term);
            }
        }
        System.out.println(answer);
        sc.close();
    }
}
